    const uint32_t deviceId_;
    const uint32_t rankId_;
    const uint32_t rankCount_;
    const hybm_role_type rankRole_;
    mf_sockaddr deviceAddress_;
    void *serverSocketHandle_{nullptr};
};
}
}
