48	constexpr uint32_t HNS_1825_DB_VENDOR_FIELD_MASK = 0x7;
49	constexpr uint32_t HNS_1825_DB_COS_SHIFT = 24;
50	constexpr uint32_t HNS_1825_MTU_SHIFT_SHIFT = 50;
51	constexpr uint8_t HNS_1825_DEFAULT_MTU_SHIFT = 4;
52	constexpr uint8_t HNS_1825_DEFAULT_DB_COS = 0x7;
53	constexpr uint32_t RDMA_CONTEXT_ENTRY_SIZE_MIN = 32;
54	constexpr uint32_t RDMA_CONTEXT_ENTRY_SIZE_MAX = 4096;
55	constexpr uint64_t HNS_1825_DB_VENDOR_SPECIFIED_MASK =
56	    (static_cast<uint64_t>(HNS_1825_DB_VENDOR_FIELD_MASK) << HNS_1825_DB_COS_SHIFT) |
57	    (static_cast<uint64_t>(HNS_1825_DB_VENDOR_FIELD_MASK) << HNS_1825_MTU_SHIFT_SHIFT);
