88	bool IsDbModeValid(int8_t dbMode) noexcept
89	{
90	    return dbMode == static_cast<int8_t>(DBMode::HW_DB) || dbMode == static_cast<int8_t>(DBMode::SW_DB);
91	}
92	
93	bool IsRdmaContextEntrySizeValid(uint32_t size) noexcept
94	{
95	    return size >= RDMA_CONTEXT_ENTRY_SIZE_MIN && size <= RDMA_CONTEXT_ENTRY_SIZE_MAX && (size & (size - 1)) == 0;
96	}
97	
98	bool IsDbVendorSpecifiedValid(uint64_t dbVendorSpecified) noexcept
99	{
100	    if (dbVendorSpecified == 0) {
101	        return false;
102	    }
103	
104	    // The transition ABI used the low byte for dbCos; only the 3-bit value is valid.
105	    if ((dbVendorSpecified & ~0xffULL) == 0) {
106	        return dbVendorSpecified <= HNS_1825_DB_VENDOR_FIELD_MASK;
107	    }
108	
109	    // SplitDb producers may not initialize the bytes after offset 56. Accept
110	    // only the current ABI's known bit-field shape to avoid treating tail data
111	    // as DbVendorSpecified.
112	    return (dbVendorSpecified & ~HNS_1825_DB_VENDOR_SPECIFIED_MASK) == 0;
113	}
114	
115	bool LooksLikeInitialSqContext(const SqContext& context) noexcept
116	{
117	    if (context.type != SQ_CONTEXT_TYPE_ROCE) {
118	        return false;
119	    }
120	
121	    /*
122	     * There is no ABI version tag in SqContext. In the SplitDb layout, the
123	     * Initial view aliases wqeSize with the low byte of the real wqeSize and
124	     * aliases qpn with the low part of dbSwVa. Validate the Initial entry
125	     * size as an additional discriminator. The supported RDMA backends use
126	     * power-of-two entries in this range; this check documents the assumption
127	     * and avoids accepting the known 256-byte SplitDb false-positive case.
128	     */
129	    const auto initial = ExtractSqContextRoceInitial(context);
130	    return initial.qpn != 0 && IsRdmaContextEntrySizeValid(initial.wqeSize) && initial.depth != 0 &&
131	           IsDbModeValid(initial.dbMode) && initial.sl <= 7;
132	}
133	
134	bool LooksLikeInitialCqContext(const CqContext& context) noexcept
135	{
136	    if (context.type != CQ_CONTEXT_TYPE_ROCE) {
137	        return false;
138	    }
139	
140	    // See LooksLikeInitialSqContext: cqeSize provides the equivalent extra ABI discriminator for CQ.
141	    const auto initial = ExtractCqContextRoceInitial(context);
142	    return initial.cqn != 0 && IsRdmaContextEntrySizeValid(initial.cqeSize) && initial.cqDepth != 0 &&
143	           IsDbModeValid(initial.dbMode);
144	}
145	
146	void DecodePackedDbVendorSpecified(uint64_t dbVendorSpecified, uint8_t& mtuShift, uint8_t& dbCos) noexcept
147	{
148	    if (dbVendorSpecified == 0) {
149	        mtuShift = HNS_1825_DEFAULT_MTU_SHIFT;
150	        dbCos = HNS_1825_DEFAULT_DB_COS;
151	        return;
152	    }
153	
154	    // A short-lived transition ABI carried vendorPrivInfo as a low-byte value.
155	    if ((dbVendorSpecified & ~0xffULL) == 0) {
156	        mtuShift = HNS_1825_DEFAULT_MTU_SHIFT;
157	        dbCos = static_cast<uint8_t>(dbVendorSpecified & HNS_1825_DB_VENDOR_FIELD_MASK);
158	        return;
159	    }
160	
161	    mtuShift = static_cast<uint8_t>((dbVendorSpecified >> HNS_1825_MTU_SHIFT_SHIFT) & HNS_1825_DB_VENDOR_FIELD_MASK);
162	    dbCos = static_cast<uint8_t>((dbVendorSpecified >> HNS_1825_DB_COS_SHIFT) & HNS_1825_DB_VENDOR_FIELD_MASK);
163	}
164	
165	DecodedRoceSqContext DecodeRoceSqContext(const SqContext& context) noexcept
166	{
167	    if (LooksLikeInitialSqContext(context)) {
168	        const auto initial = ExtractSqContextRoceInitial(context);
169	        return {
170	            "initial",
171	            initial.qpn,
172	            initial.sqVa,
173	            initial.wqeSize,
174	            initial.depth,
175	            initial.headAddr,
176	            initial.tailAddr,
177	            initial.dbVa,
178	            0,
179	            (initial.dbMode == 0) ? DBMode::HW_DB : DBMode::SW_DB,
180	            initial.sl,
181	            HNS_1825_DEFAULT_MTU_SHIFT,
182	            HNS_1825_DEFAULT_DB_COS};
183	    }
184	
185	    const auto splitDb = ExtractSqContextRoceSplitDb(context);
186	    uint8_t mtuShift = splitDb.mtuShift;
187	    uint8_t dbCos = HNS_1825_DEFAULT_DB_COS;
188	    const auto vendor = ExtractSqContextRoceVendorSpecified(context);
189	    const char* abiName = "split-db-mtushift";
190	    if (IsDbVendorSpecifiedValid(vendor.DbVendorSpecified)) {
191	        abiName = "db-vendor-specified";
192	        DecodePackedDbVendorSpecified(vendor.DbVendorSpecified, mtuShift, dbCos);
193	    }
194	
195	    return {abiName,          splitDb.qpn,      splitDb.sqVa,   splitDb.wqeSize, splitDb.depth,
196	            splitDb.headAddr, splitDb.tailAddr, splitDb.dbHwVa, splitDb.dbSwVa,  DBMode::SW_DB,
197	            splitDb.sl,       mtuShift,         dbCos};
198	}
199	
200	DecodedRoceCqContext DecodeRoceCqContext(const CqContext& context) noexcept
201	{
202	    if (LooksLikeInitialCqContext(context)) {
203	        const auto initial = ExtractCqContextRoceInitial(context);
204	        return {
205	            "initial",
206	            initial.cqn,
207	            initial.cqVa,
208	            initial.cqeSize,
209	            initial.cqDepth,
210	            initial.headAddr,
211	            initial.tailAddr,
212	            initial.dbVa,
213	            0,
214	            (initial.dbMode == 0) ? DBMode::HW_DB : DBMode::SW_DB};
215	    }
216	
217	    const auto splitDb = ExtractCqContextRoceSplitDb(context);
218	    const auto vendor = ExtractCqContextRoceVendorSpecified(context);
219	    return {
220	        IsDbVendorSpecifiedValid(vendor.DbVendorSpecified) ? "db-vendor-specified" : "split-db",
221	        splitDb.cqn,
222	        splitDb.cqVa,
223	        splitDb.cqeSize,
224	        splitDb.cqDepth,
225	        splitDb.headAddr,
226	        splitDb.tailAddr,
227	        splitDb.dbHwVa,
228	        splitDb.dbSwVa,
229	        DBMode::SW_DB};
230	}
