239	Result RdmaTransportManagerV2::OpenDevice(const TransportOptions& options)
240	{
241	    int32_t userId = -1;
242	    int32_t logicId = -1;
243	
244	    SHM_LOG_DEBUG("rank[" << rankId_ << "] begin to open device with " << options);
245	    auto ret = DlAclApi::AclrtGetDevice(&userId);
246	    SHM_ASSERT_LOG_AND_RETURN(
247	        ret == 0 && userId >= 0, "AclrtGetDevice() return=" << ret << ", output deviceId=" << userId,
248	        ACLSHMEM_INNER_ERROR);
249	
250	    ret = DlAclApi::RtGetLogicDevIdByUserDevId(userId, &logicId);
251	    SHM_ASSERT_LOG_AND_RETURN(
252	        ret == 0 && logicId >= 0, "RtGetLogicDevIdByUserDevId() return=" << ret << ", output deviceId=" << logicId,
253	        ACLSHMEM_INNER_ERROR);
254	
255	    int32_t phyId = -1;
256	    // HCCP/topo use global phyId; pass userId to deprecated API (MR !407), not logicId.
257	    ret = DlAclApi::AclrtGetPhyDevIdByLogicDevId(userId, &phyId);
258	    SHM_ASSERT_LOG_AND_RETURN(
259	        ret == 0 && phyId >= 0,
260	        "AclrtGetPhyDevIdByLogicDevId() return=" << ret << ", userId=" << userId << ", logicDeviceId=" << logicId
261	                                                 << ", output phyId=" << phyId,
262	        ACLSHMEM_INNER_ERROR);
263	    phyId_ = static_cast<uint32_t>(phyId);
264	
265	    rankId_ = options.rankId;
266	    rankCount_ = options.rankCount;
267	    role_ = options.role;
268	    qpNum_ = options.rdmaQpConfig.qpNum;
269	    if (qpNum_ == 0 || qpNum_ > ACLSHMEM_MAX_QP_NUM) {
270	        SHM_LOG_ERROR("rank[" << rankId_ << "] invalid rdma qp num: " << qpNum_);
271	        return ACLSHMEM_INVALID_PARAM;
272	    }
273	#if !defined(ACLSHMEMI_RDMA_K_BACKEND_XSCALE)
274	    if (qpNum_ != 1U) {
275	        SHM_LOG_ERROR("rank[" << rankId_ << "] RDMA multi-QP is only supported on XSCALE, qpNum=" << qpNum_);
276	        return ACLSHMEM_NOT_SUPPORTED;
277	    }
278	#endif
279	
280	    if (options.type == IpV4) {
281	        deviceIp_.type = IpV4;
282	    } else if (options.type == IpV6) {
283	        deviceIp_.type = IpV6;
284	    }
285	
286	    if (!TopoReader::ParseRdmaNetAddr(phyId_, deviceIp_)) {
287	        SHM_LOG_ERROR("rank[" << rankId_ << "] ParseRdmaNetAddr failed for phyId " << phyId_);
288	        return ACLSHMEM_INNER_ERROR;
289	    }
290	
291	    ret = CreateEndpoint();
292	    if (ret != ACLSHMEM_SUCCESS) {
293	        SHM_LOG_ERROR("rank[" << rankId_ << "] CreateEndpoint failed: " << ret);
294	        return ret;
295	    }
296	
297	    ret = InitActualListenPort();
298	    if (ret != ACLSHMEM_SUCCESS) {
299	        DestroyEndpoint();
300	        return ret;
301	    }
302	
303	    nicInfo_ = GenerateDeviceNic(deviceIp_, devicePort_);
304	    SHM_LOG_DEBUG("rank[" << rankId_ << "] nicInfo_=" << nicInfo_);
305	
306	    if (!ReserveRdmaInfoSpace()) {
307	        SHM_LOG_ERROR("rank[" << rankId_ << "] reserve rdma info space failed.");
308	        DestroyEndpoint();
309	        return ACLSHMEM_INNER_ERROR;
310	    }
311	
312	    SHM_LOG_INFO("rank[" << rankId_ << "] open device with " << options << " success.");
313	    return ACLSHMEM_SUCCESS;
314	}
315	
316	Result RdmaTransportManagerV2::InitActualListenPort()
317	{
318	    if (endpointHandle_ == nullptr) {
319	        SHM_LOG_ERROR("rank[" << rankId_ << "] endpoint not created, cannot get listen port.");
320	        return ACLSHMEM_INNER_ERROR;
321	    }
322	
323	    uint32_t listenPort = 0U;
324	    HcommResult hret = DlHcommApi::HcommEndpointGetListenPort(endpointHandle_, &listenPort);
325	    if (hret != 0) {
326	        SHM_LOG_ERROR("rank[" << rankId_ << "] HcommEndpointGetListenPort failed: " << hret);
327	        return ACLSHMEM_INNER_ERROR;
328	    }
329	    if (listenPort == 0U || listenPort > std::numeric_limits<uint16_t>::max()) {
330	        SHM_LOG_ERROR("rank[" << rankId_ << "] invalid actual rdma listen port: " << listenPort);
331	        return ACLSHMEM_INNER_ERROR;
332	    }
333	
334	    devicePort_ = static_cast<uint16_t>(listenPort);
335	    SHM_LOG_INFO("rank[" << rankId_ << "] actual rdma listen port: " << devicePort_);
336	    return ACLSHMEM_SUCCESS;
337	}
338	
339	Result RdmaTransportManagerV2::BuildEndpointDesc(EndpointDesc& desc)
340	{
341	    EndpointDescInit(&desc, 1);
342	
343	    desc.protocol = COMM_PROTOCOL_ROCE;
344	    if (deviceIp_.type == IpV4) {
345	        desc.commAddr.type = COMM_ADDR_TYPE_IP_V4;
346	        desc.commAddr.addr = deviceIp_.ip.ipv4;
347	    } else if (deviceIp_.type == IpV6) {
348	        desc.commAddr.type = COMM_ADDR_TYPE_IP_V6;
349	        desc.commAddr.addr6 = deviceIp_.ip.ipv6;
350	    } else {
351	        SHM_LOG_ERROR("rank[" << rankId_ << "] unsupported ip type: " << deviceIp_.type);
352	        return ACLSHMEM_INVALID_PARAM;
353	    }
354	
355	    desc.loc.locType = ENDPOINT_LOC_TYPE_HOST;
356	    desc.loc.device.devPhyId = phyId_;
357	    return ACLSHMEM_SUCCESS;
358	}
359	
360	Result RdmaTransportManagerV2::CreateEndpoint()
361	{
362	    if (endpointHandle_ != nullptr) {
363	        SHM_LOG_INFO("rank[" << rankId_ << "] endpoint already created.");
364	        return ACLSHMEM_SUCCESS;
365	    }
366	
367	    EndpointDesc endpointDesc{};
368	    auto ret = BuildEndpointDesc(endpointDesc);
369	    if (ret != ACLSHMEM_SUCCESS) {
370	        SHM_LOG_ERROR("rank[" << rankId_ << "] build endpoint desc failed: " << ret);
371	        return ret;
372	    }
373	
374	    SHM_LOG_DEBUG(
375	        "rank[" << rankId_ << "] HcommEndpointCreate, protocol=COMM_PROTOCOL_ROCE, locType=ENDPOINT_LOC_TYPE_HOST"
376	                << ", devPhyId=" << phyId_);
377	    HcommResult hret = DlHcommApi::HcommEndpointCreate(&endpointDesc, &endpointHandle_);
378	    if (hret != 0) {
379	        SHM_LOG_ERROR("rank[" << rankId_ << "] HcommEndpointCreate failed: " << hret);
380	        return ACLSHMEM_INNER_ERROR;
381	    }
382	
383	    SHM_LOG_INFO("rank[" << rankId_ << "] HcommEndpointCreate success, endpointHandle=" << endpointHandle_);
384	    return ACLSHMEM_SUCCESS;
385	}
386	
387	void RdmaTransportManagerV2::DestroyEndpoint()
388	{
389	    if (atomicMemHandle_ != nullptr && endpointHandle_ != nullptr) {
390	        HcommResult hret = DlHcommApi::HcommMemUnreg(endpointHandle_, atomicMemHandle_);
391	        if (hret != 0) {
392	            SHM_LOG_WARN("rank[" << rankId_ << "] HcommMemUnreg for atomic memory failed: " << hret);
393	        }
394	        atomicMemHandle_ = nullptr;
395	        atomicLkey_ = 0;
396	    }
397	
398	    if (endpointHandle_ != nullptr) {
399	        HcommResult hret = DlHcommApi::HcommEndpointDestroy(endpointHandle_);
400	        if (hret != 0) {
401	            SHM_LOG_WARN("rank[" << rankId_ << "] HcommEndpointDestroy failed: " << hret);
402	        }
403	        endpointHandle_ = nullptr;
404	    }
405	
406	    if (atomicSharedMemory_ != nullptr) {
407	        DlAclApi::AclrtFree(atomicSharedMemory_);
408	        atomicSharedMemory_ = nullptr;
409	    }
410	
411	    if (qpInfo_ != nullptr) {
412	        DlAclApi::AclrtFree(reinterpret_cast<void*>(qpInfo_));
413	        qpInfo_ = nullptr;
414	    }
415	}
