417	Result RdmaTransportManagerV2::CloseDevice()
418	{
419	    DlHcommApi::HcommChannelDestroy(reinterpret_cast<const ChannelHandle*>(channelPtrs_.data()), channelPtrs_.size());
420	    channelPtrs_.clear();
421	
422	    ClearAllRegisterMRs();
423	    DestroyEndpoint();
424	    return ACLSHMEM_SUCCESS;
425	}
