543	Result RdmaTransportManagerV2::Connect()
544	{
545	    SHM_LOG_DEBUG("rank[" << rankId_ << "] RdmaTransportManagerV2 Connect");
546	
547	    if (endpointHandle_ == nullptr) {
548	        SHM_LOG_ERROR("rank[" << rankId_ << "] endpoint not created, please call Prepare first");
549	        return ACLSHMEM_INNER_ERROR;
550	    }
551	
552	    auto consistencyRet = CheckQpNumConsistency();
553	    if (consistencyRet != ACLSHMEM_SUCCESS) {
554	        return consistencyRet;
555	    }
556	
557	    const uint64_t peerCount = static_cast<uint64_t>(rankCount_ - 1);
558	    const uint64_t channelNum64 = peerCount * static_cast<uint64_t>(qpNum_);
559	    if (channelNum64 > std::numeric_limits<uint32_t>::max()) {
560	        SHM_LOG_ERROR(
561	            "rank[" << rankId_ << "] channel count overflow, peerCount=" << peerCount << ", qpNum=" << qpNum_);
562	        return ACLSHMEM_INVALID_PARAM;
563	    }
564	    uint32_t channelNum = static_cast<uint32_t>(channelNum64);
565	
566	    if (!RegisterAtomicMemory()) {
567	        return ACLSHMEM_INNER_ERROR;
568	    }
569	
570	    HcommMemHandle primaryMemHandle = nullptr;
571	    auto ret = GetPrimaryMemoryHandle(primaryMemHandle);
572	    if (ret != ACLSHMEM_SUCCESS) {
573	        return ret;
574	    }
575	
576	    std::vector<HcommChannelDesc> channelDescs(channelNum);
577	    auto desc_init_ret = ShmemHcommChannelDescInit(channelDescs.data(), channelNum);
578	    if (desc_init_ret != 0) {
579	        SHM_LOG_ERROR("HcommChannelDescInit failed, ret = " << desc_init_ret);
580	        return ACLSHMEM_INNER_ERROR;
581	    }
582	    std::vector<HcommMemHandle> channelMemHandles(static_cast<size_t>(channelNum) * RDMA_CHANNEL_MEM_HANDLE_NUM);
583	    channelNames_.clear();
584	    channelNames_.resize(channelNum);
585	
586	    uint8_t roceTc = GetEnvUint8("HCCL_RDMA_TC", DEFAULT_RDMA_TC, 0, 255, true);
587	    uint8_t roceSl = GetEnvUint8("HCCL_RDMA_SL", DEFAULT_RDMA_SL, 0, 7);
588	
589	    uint32_t chIdx = 0;
590	    for (uint32_t remoteRank = 0; remoteRank < rankCount_; ++remoteRank) {
591	        if (remoteRank == rankId_) {
592	            continue;
593	        }
594	
595	        auto rankIt = rankInfo_.find(remoteRank);
596	        if (rankIt == rankInfo_.end()) {
597	            SHM_LOG_ERROR("rank[" << rankId_ << "] rank " << remoteRank << " not found in rankInfo_");
598	            return ACLSHMEM_INVALID_PARAM;
599	        }
600	
601	        uint16_t remotePort = 0U;
602	        auto portRet = GetDeviceNicPort(rankIt->second.network, remotePort);
603	        if (portRet != ACLSHMEM_SUCCESS) {
604	            SHM_LOG_ERROR("rank[" << rankId_ << "] rank " << remoteRank << " has invalid rdma port.");
605	            return portRet;
606	        }
607	        const bool isServer = (rankId_ < remoteRank);
608	        for (uint32_t qpIdx = 0; qpIdx < qpNum_; ++qpIdx) {
609	            auto& desc = channelDescs[chIdx];
610	            desc.remoteEndpoint.protocol = COMM_PROTOCOL_ROCE;
611	            if (rankIt->second.network.type == IpV4) {
612	                desc.remoteEndpoint.commAddr.type = COMM_ADDR_TYPE_IP_V4;
613	                desc.remoteEndpoint.commAddr.addr = rankIt->second.network.ip.ipv4.sin_addr;
614	            } else {
615	                desc.remoteEndpoint.commAddr.type = COMM_ADDR_TYPE_IP_V6;
616	                desc.remoteEndpoint.commAddr.addr6 = rankIt->second.network.ip.ipv6.sin6_addr;
617	            }
618	            desc.notifyNum = 3;
619	            desc.exchangeAllMems = false;
620	            HcommMemHandle* memHandles = channelMemHandles.data() + chIdx * RDMA_CHANNEL_MEM_HANDLE_NUM;
621	            memHandles[0] = primaryMemHandle;
622	            memHandles[1] = atomicMemHandle_;
623	            desc.memHandles = memHandles;
624	            desc.memHandleNum = RDMA_CHANNEL_MEM_HANDLE_NUM;
625	            desc.roceAttr.queueNum = 1;
626	            desc.roceAttr.tc = roceTc;
627	            desc.roceAttr.sl = roceSl;
628	            desc.roceAttr.retryCnt = DEFAULT_ROCE_RETRY_CNT;
629	            desc.roceAttr.retryInterval = DEFAULT_ROCE_RETRY_INTERVAL;
630	            SetChannelDescCqAttrFlags(desc, cqAttrFlags_);
631	            desc.socket = nullptr;
632	            desc.role = isServer ? HCOMM_SOCKET_ROLE_SERVER : HCOMM_SOCKET_ROLE_CLIENT;
633	            desc.port = isServer ? devicePort_ : remotePort;
634	            channelNames_[chIdx] = BuildStableChannelName(rankId_, remoteRank, qpIdx);
635	            desc.channelName = channelNames_[chIdx].c_str();
636	            SHM_LOG_INFO(
637	                "rank[" << rankId_ << "] rdma channel to rank[" << remoteRank << "] qp=" << qpIdx
638	                        << " role=" << (isServer ? "server" : "client") << ", port=" << desc.port
639	                        << ", name=" << channelNames_[chIdx]);
640	            ++chIdx;
641	        }
642	    }
643	
644	    channelPtrs_.resize(channelNum);
645	
646	    auto hcommRet = DlHcommApi::HcommChannelCreate(
647	        endpointHandle_, COMM_ENGINE_AIV, channelDescs.data(), channelNum,
648	        reinterpret_cast<ChannelHandle*>(channelPtrs_.data()));
649	    if (hcommRet != 0) {
650	        SHM_LOG_ERROR("rank[" << rankId_ << "] HcommChannelCreate failed: " << hcommRet);
651	        channelPtrs_.clear();
652	        return ACLSHMEM_INNER_ERROR;
653	    }
654	    SHM_LOG_DEBUG("rank[" << rankId_ << "] HcommChannelCreate success, channelNum=" << channelNum);
655	
656	    auto channelGuard = shm::utils::make_scope_guard(channelPtrs_.data(), [this, channelNum](ChannelHandle*) {
657	        DlHcommApi::HcommChannelDestroy(reinterpret_cast<const ChannelHandle*>(channelPtrs_.data()), channelNum);
658	        channelPtrs_.clear();
659	    });
660	
661	    const uint32_t pollIntervalMs = channelNum * CHANNEL_STATUS_POLL_INTERVAL_PER_CH_MS;
662	    const uint32_t pollTimeoutMs = channelNum * CHANNEL_STATUS_POLL_TIMEOUT_PER_CH_MS;
663	    std::vector<int32_t> statusList(channelNum, HCOMM_CHANNEL_STATUS_CONNECTING);
664	    bool allReady = false;
665	    bool connectFailed = false;
666	    uint32_t elapsedMs = 0;
667	    while (elapsedMs <= pollTimeoutMs) {
668	        auto statusRet = DlHcommApi::HcommChannelGetStatus(channelPtrs_.data(), channelNum, statusList.data());
669	        if (statusRet != 0) {
670	            SHM_LOG_ERROR("rank[" << rankId_ << "] HcommChannelGetStatus failed: " << statusRet);
671	            return ACLSHMEM_INNER_ERROR;
672	        }
673	
674	        allReady = true;
675	        connectFailed = false;
676	        for (uint32_t i = 0; i < channelNum; ++i) {
677	            const int32_t status = statusList[i];
678	            if (status == HCOMM_CHANNEL_STATUS_READY) {
679	                continue;
680	            }
681	            allReady = false;
682	            if (status == HCOMM_CHANNEL_STATUS_CONNECTING) {
683	                continue; // 建链中，继续等待
684	            }
685	            if (status == HCOMM_CHANNEL_STATUS_FAILED) {
686	                SHM_LOG_ERROR("rank[" << rankId_ << "] channel[" << i << "] connect failed, status=" << status);
687	                connectFailed = true;
688	            } else if (status == HCOMM_CHANNEL_STATUS_TIMEOUT) {
689	                SHM_LOG_ERROR("rank[" << rankId_ << "] channel[" << i << "] connect timeout, status=" << status);
690	                connectFailed = true;
691	            } else {
692	                SHM_LOG_ERROR("rank[" << rankId_ << "] channel[" << i << "] unknown status=" << status);
693	                connectFailed = true;
694	            }
695	        }
696	        if (allReady) {
697	            break;
698	        }
699	        if (connectFailed) {
700	            SHM_LOG_ERROR(
701	                "rank[" << rankId_ << "] channel connect failed, stop polling, channelNum=" << channelNum
702	                        << ", elapsedMs=" << elapsedMs);
703	            return ACLSHMEM_INNER_ERROR;
704	        }
705	        std::this_thread::sleep_for(std::chrono::milliseconds(pollIntervalMs));
706	        elapsedMs += pollIntervalMs;
707	    }
708	
709	    if (!allReady) {
710	        SHM_LOG_ERROR(
711	            "rank[" << rankId_ << "] wait channel connect timeout, channelNum=" << channelNum << ", pollIntervalMs="
712	                    << pollIntervalMs << ", pollTimeoutMs=" << pollTimeoutMs << ", elapsedMs=" << elapsedMs);
713	        return ACLSHMEM_INNER_ERROR;
714	    }
715	    SHM_LOG_DEBUG("rank[" << rankId_ << "] all channels connected, elapsedMs=" << elapsedMs);
716	
717	    auto fillRet = FillRdmaInfo();
718	    if (fillRet != ACLSHMEM_SUCCESS) {
719	        SHM_LOG_ERROR("rank[" << rankId_ << "] FillRdmaInfo failed: " << fillRet);
720	        return fillRet;
721	    }
722	
723	    channelGuard.release();
724	    SHM_LOG_INFO("rank[" << rankId_ << "] Connect success, created " << channelNum << " channels");
725	    return ACLSHMEM_SUCCESS;
726	}
