728	Result RdmaTransportManagerV2::CheckQpNumConsistency() const
729	{
730	    if (rankCount_ <= 1) {
731	        return ACLSHMEM_SUCCESS;
732	    }
733	    if (g_boot_handle.allgather == nullptr) {
734	        SHM_LOG_ERROR("rank[" << rankId_ << "] bootstrap allgather is unavailable for QP consistency check");
735	        return ACLSHMEM_INNER_ERROR;
736	    }
737	
738	    std::vector<uint32_t> allQpNums(rankCount_, 0);
739	    auto ret = g_boot_handle.allgather(&qpNum_, allQpNums.data(), sizeof(qpNum_), &g_boot_handle);
740	    if (ret != 0) {
741	        SHM_LOG_ERROR("rank[" << rankId_ << "] allgather rdma qp num failed: " << ret);
742	        return ACLSHMEM_INNER_ERROR;
743	    }
744	    for (uint32_t rank = 0; rank < rankCount_; ++rank) {
745	        if (allQpNums[rank] != qpNum_) {
746	            SHM_LOG_ERROR(
747	                "rank[" << rankId_ << "] inconsistent rdma qp num: local=" << qpNum_ << ", rank[" << rank
748	                        << "]=" << allQpNums[rank]);
749	            return ACLSHMEM_INVALID_PARAM;
750	        }
751	    }
752	    return ACLSHMEM_SUCCESS;
753	}
