1100	
1101	    void* ptr = nullptr;
1102	    auto oneQpSize = 2U * (sizeof(AiQpRMAWQ) + sizeof(AiQpRMACQ)) + sizeof(RdmaMemRegionInfo);
1103	    const uint64_t qpEntryCount = static_cast<uint64_t>(rankCount_) * qpNum_;
1104	    qpInfoSize_ = sizeof(AiQpRMAQueueInfo) + oneQpSize * qpEntryCount;
