#ifndef MF_HYBRID_DEVICE_RDMA_COMMON_H
#define MF_HYBRID_DEVICE_RDMA_COMMON_H

#include <arpa/inet.h>
#include <ostream>
#include <sstream>
#include <map>
#include "sotre_net.h"
#include "mem_entity_def.h"
#include "transport_def.h"
