53	Result RdmaTransportManager::OpenDevice(const TransportOptions& options)
54	{
55	    int32_t userId = -1;
56	    int32_t logicId = -1;
57	
58	    SHM_LOG_DEBUG(rankId_ << " begin to open device with " << options);
59	    auto ret = DlAclApi::AclrtGetDevice(&userId);
60	    SHM_ASSERT_LOG_AND_RETURN(
61	        ret == 0 && userId >= 0, "AclrtGetDevice() return=" << ret << ", output deviceId=" << userId,
62	        ACLSHMEM_DL_FUNC_FAILED);
63	
64	    ret = DlAclApi::RtGetLogicDevIdByUserDevId(userId, &logicId);
65	    SHM_ASSERT_LOG_AND_RETURN(
66	        ret == 0 && logicId >= 0, "RtGetLogicDevIdByUserDevId() return=" << ret << ", output deviceId=" << logicId,
67	        ACLSHMEM_DL_FUNC_FAILED);
68	
69	    int32_t phyId = -1;
70	    // HCCP/topo use global phyId; pass userId to deprecated API (MR !407), not logicId.
71	    ret = DlAclApi::AclrtGetPhyDevIdByLogicDevId(userId, &phyId);
72	    SHM_ASSERT_LOG_AND_RETURN(
73	        ret == 0 && phyId >= 0,
74	        "AclrtGetPhyDevIdByLogicDevId() return=" << ret << ", userId=" << userId << ", logicDeviceId=" << logicId
75	                                                 << ", output phyId=" << phyId,
76	        ACLSHMEM_DL_FUNC_FAILED);
77	
78	    deviceId_ = static_cast<uint32_t>(logicId);
79	    phyId_ = static_cast<uint32_t>(phyId);
80	    SHM_LOG_INFO(
81	        rankId_ << " resolved device mapping: userId=" << userId << ", logicDeviceId=" << deviceId_
82	                << ", phyId=" << phyId_);
83	    rankId_ = options.rankId;
84	    rankCount_ = options.rankCount;
85	    role_ = options.role;
86	    ret = ParseDeviceNic(options.nic, devicePort_);
87	    if (ret != ACLSHMEM_SUCCESS) {
88	        SHM_LOG_ERROR(rankId_ << " parse input nic(" << options.nic << ") failed!");
89	        return ACLSHMEM_INVALID_PARAM;
90	    }
91	
92	    if (options.type == IpV4) {
93	        deviceIp_.type = IpV4;
94	    } else if (options.type == IpV6) {
95	        deviceIp_.type = IpV6;
96	    }
97	
98	    if (!PrepareOpenDevice(userId, phyId_, rankCount_, deviceIp_, rdmaHandle_)) {
99	        SHM_LOG_ERROR("phyId=" << phyId_ << " PrepareOpenDevice failed.");
100	        return ACLSHMEM_INNER_ERROR;
101	    }
102	    nicInfo_ = GenerateDeviceNic(deviceIp_, devicePort_);
103	
104	    mf_sockaddr deviceAddr;
105	    InitializeDeviceAddress(deviceAddr);
106	    if (role_ == hybm_role_type::HYBM_ROLE_PEER) {
107	        qpManager_ = std::make_shared<FixedRanksQpManager>(userId, phyId_, rankId_, rankCount_, deviceAddr);
108	    } else {
109	        qpManager_ = std::make_shared<DynamicRanksQpManager>(
110	            userId, phyId_, rankId_, rankCount_, deviceAddr, role_ == hybm_role_type::HYBM_ROLE_RECEIVER);
111	    }
112	
113	    deviceChipInfo_ = std::make_shared<DeviceChipInfo>(userId);
114	    ret = deviceChipInfo_->Init();
115	    if (ret != ACLSHMEM_SUCCESS) {
116	        SHM_LOG_ERROR(rankId_ << " device info init failed: " << ret);
117	        return ret;
118	    }
119	    SHM_LOG_INFO(rankId_ << " open device with " << options << " success.");
120	    return ACLSHMEM_SUCCESS;
121	}
