132	Result RdmaTransportManager::RegisterMemoryRegion(const TransportMemoryRegion& mr)
133	{
134	    void* mrHandle = nullptr;
135	    HccpMrInfo info{};
136	    info.addr = (void*)(ptrdiff_t)mr.addr;
137	    info.size = mr.size;
138	    info.access = mr.access;
139	    auto ret = DlHccpApi::RaRegisterMR(rdmaHandle_, &info, mrHandle);
140	    if (ret != 0) {
141	        SHM_LOG_ERROR(rankId_ << " register MR=" << mr << " failed: " << ret);
142	        return ACLSHMEM_DL_FUNC_FAILED;
143	    }
144	
145	    RegMemResult result{mr.addr, mr.size, mrHandle, info.lkey, info.rkey};
146	    SHM_LOG_DEBUG(rankId_ << " register MR result=" << result);
147	
148	    registerMRS_.emplace(mr.addr, result);
149	    ret = qpManager_->SetLocalMemories(registerMRS_);
150	    if (ret != ACLSHMEM_SUCCESS) {
151	        SHM_LOG_ERROR(rankId_ << " qp manager set mr failed: " << ret);
152	        return ret;
153	    }
154	
155	    return ACLSHMEM_SUCCESS;
156	}
