158	Result RdmaTransportManager::UnregisterMemoryRegion(uint64_t addr)
159	{
160	    auto pos = registerMRS_.find(addr);
161	    if (pos == registerMRS_.end()) {
162	        SHM_LOG_ERROR(rankId_ << " input address not register!");
163	        return ACLSHMEM_INVALID_PARAM;
164	    }
165	
166	    auto ret = DlHccpApi::RaDeregisterMR(rdmaHandle_, pos->second.mrHandle);
167	    if (ret != 0) {
168	        SHM_LOG_ERROR(rankId_ << " Unregister MR addr failed: " << ret);
169	        return ACLSHMEM_DL_FUNC_FAILED;
170	    }
171	
172	    registerMRS_.erase(pos);
173	    ret = qpManager_->SetLocalMemories(registerMRS_);
174	    if (ret != ACLSHMEM_SUCCESS) {
175	        SHM_LOG_ERROR(rankId_ << " qp manager set mr failed: " << ret);
176	        return ret;
177	    }
178	    return ACLSHMEM_SUCCESS;
179	}
