181	Result RdmaTransportManager::QueryMemoryKey(uint64_t addr, TransportMemoryKey& key)
182	{
183	    RegMemKeyUnion keyUnion{};
184	    auto pos = registerMRS_.lower_bound(addr);
185	    if (pos == registerMRS_.end() || pos->first + pos->second.size <= addr) {
186	        SHM_LOG_ERROR(rankId_ << " input address not register");
187	        return ACLSHMEM_INVALID_PARAM;
188	    }
189	
190	    keyUnion.deviceKey = pos->second;
191	
192	    key = keyUnion.commonKey;
193	    return ACLSHMEM_SUCCESS;
194	}
