196	Result RdmaTransportManager::ParseMemoryKey(const TransportMemoryKey& key, uint64_t& addr, uint64_t& size)
197	{
198	    RegMemKeyUnion keyUnion{};
199	    keyUnion.commonKey = key;
200	    if (keyUnion.deviceKey.type != TT_HCCP) {
201	        SHM_LOG_ERROR(rankId_ << " parse memory key type invalid: " << keyUnion.deviceKey.type);
202	        return ACLSHMEM_INNER_ERROR;
203	    }
204	
205	    addr = keyUnion.deviceKey.address;
206	    size = keyUnion.deviceKey.size;
207	    return ACLSHMEM_SUCCESS;
