322	bool RdmaTransportManager::PrepareOpenDevice(
323	    uint32_t userId, uint32_t phyId, uint32_t rankCount, net_addr_t& deviceIp, void*& rdmaHandle)
324	{
325	    // If can get rdmaHandle, maybe the device has been opened, can try get rdmaHandle directly.
326	    bool referenced = false;
327	    if (TryGetRdmaHandleAndReferenceManagedRa(phyId, rdmaHandle, referenced)) {
328	        if (rdmaHandle != nullptr) {
329	            if (!RetireDeviceIp(phyId, deviceIp)) {
330	                SHM_LOG_ERROR("phyId=" << phyId << " RetireDeviceIp failed.");
331	                if (referenced) {
332	                    RaDeinit(phyId);
333	                }
334	                return false;
335	            }
336	            raReferenced_ = referenced;
337	            SHM_LOG_DEBUG("phyId=" << phyId << " Had prepared device and get rdmaHandle success.");
338	            return true;
339	        }
340	        SHM_LOG_INFO("phyId=" << phyId << " Had prepared device, but rdmaHandle is null, need init again.");
341	    }
342	    if (!OpenTsd(userId, rankCount)) {
343	        SHM_LOG_ERROR("phyId=" << phyId << " open tsd failed.");
344	        return false;
345	    }
346	
347	    if (!RaInit(phyId)) {
348	        SHM_LOG_ERROR("phyId=" << phyId << " RaInit failed.");
349	        return false;
350	    }
351	    raReferenced_ = true;
352	
353	    if (!RetireDeviceIp(phyId, deviceIp)) {
354	        SHM_LOG_ERROR("phyId=" << phyId << " RetireDeviceIp failed.");
355	        return false;
356	    }
357	
358	    if (!RaRdevInit(phyId, deviceIp, rdmaHandle)) {
359	        SHM_LOG_ERROR("phyId=" << phyId << " RaRdevInit failed.");
360	        return false;
361	    }
362	    return true;
363	}
364	
365	bool RdmaTransportManager::TryGetRdmaHandleAndReferenceManagedRa(uint32_t phyId, void*& rdmaHandle, bool& referenced)
366	{
367	    referenced = false;
368	    std::lock_guard<std::mutex> lock(raMutex_);
369	    if (DlHccpApi::RaRdevGetHandle(phyId, rdmaHandle) != 0) {
370	        return false;
371	    }
372	
373	    auto it = raInstances_.find(phyId);
374	    if (rdmaHandle != nullptr && it != raInstances_.end() && it->second.refCount != 0) {
375	        ++it->second.refCount;
376	        it->second.rdmaHandle = rdmaHandle;
377	        referenced = true;
378	        SHM_LOG_INFO("phyId=" << phyId << " reference managed ra, ref=" << it->second.refCount << ".");
379	    }
380	    return true;
381	}
