383	bool RdmaTransportManager::OpenTsd(uint32_t userId, uint32_t rankCount)
384	{
385	    std::lock_guard<std::mutex> lock(raMutex_);
386	    if (tsdOpened_) {
387	        SHM_LOG_INFO("userId=" << userId << " tsd already opened.");
388	        return true;
389	    }
390	
391	    auto res = DlHccpApi::TsdOpen(userId, rankCount);
392	    if (res != 0) {
393	        SHM_LOG_ERROR("TsdOpen for (userId=" << userId << ", rankCount=" << rankCount << ") failed: " << res);
394	        return false;
395	    }
396	
397	    SHM_LOG_DEBUG("open tsd for user id: " << userId << ", rank count: " << rankCount << " success.");
398	    tsdOpened_ = true;
399	    return true;
400	}
401	
402	bool RdmaTransportManager::RaInit(uint32_t phyId)
403	{
404	    std::lock_guard<std::mutex> lock(raMutex_);
405	    auto& state = raInstances_[phyId];
406	    if (state.refCount != 0) {
407	        ++state.refCount;
408	        SHM_LOG_INFO("phyId=" << phyId << " ra already initialized, ref=" << state.refCount << ".");
409	        return true;
410	    }
411	
412	    const std::chrono::seconds WAIT_TIME(3);
413	    HccpRaInitConfig initConfig{};
414	    initConfig.phyId = phyId;
415	    initConfig.nicPosition = NETWORK_OFFLINE;
416	    initConfig.hdcType = 6; // HDC_SERVICE_TYPE_RDMA = 6
417	    SHM_LOG_DEBUG("phyId=" << phyId << " RaInit=" << initConfig);
418	    std::this_thread::sleep_for(WAIT_TIME); // avoid hccl init conflict
419	    auto ret = DlHccpApi::RaInit(initConfig);
420	    if (ret != 0) {
421	        SHM_LOG_WARN("phyId=" << phyId << " Hccp Init RA failed: " << ret);
422	        // maybe hccl have already initialized ra, wait 3s then return true.
423	        std::this_thread::sleep_for(WAIT_TIME);
424	        state.refCount = 1;
425	        state.selfOwned = false;
426	        return true;
427	    }
428	
429	    SHM_LOG_DEBUG("phyId=" << phyId << " ra init success.");
430	    state.refCount = 1;
431	    state.selfOwned = true;
432	    return true;
433	}
434	
435	void RdmaTransportManager::RaDeinit(uint32_t phyId)
436	{
437	    std::lock_guard<std::mutex> lock(raMutex_);
438	    auto it = raInstances_.find(phyId);
439	    if (it == raInstances_.end() || it->second.refCount == 0) {
440	        SHM_LOG_WARN("phyId=" << phyId << " not ra init.");
441	        return;
442	    }
443	
444	    --it->second.refCount;
445	    SHM_LOG_INFO("phyId=" << phyId << " release ra, ref=" << it->second.refCount << ".");
446	    if (it->second.refCount != 0) {
447	        return;
448	    }
449	
450	    if (!it->second.selfOwned) {
451	        SHM_LOG_INFO("phyId=" << phyId << " skip RaDeinit in shmem.");
452	        raInstances_.erase(it);
453	        if (raInstances_.empty()) {
454	            tsdOpened_ = false;
455	        }
456	        return;
457	    }
458	
459	    HccpRaInitConfig deinitConfig{};
460	    deinitConfig.phyId = phyId;
461	    deinitConfig.nicPosition = NETWORK_OFFLINE;
462	    deinitConfig.hdcType = 6; // HDC_SERVICE_TYPE_RDMA = 6
463	    auto ret = DlHccpApi::RaDeinit(deinitConfig);
464	    if (ret != 0) {
465	        SHM_LOG_WARN("phyId=" << phyId << " Hccp Deinit RA failed: " << ret);
466	    } else {
467	        SHM_LOG_DEBUG("phyId=" << phyId << " ra deinit success.");
468	    }
469	
470	    raInstances_.erase(it);
471	    if (raInstances_.empty()) {
472	        tsdOpened_ = false;
473	    }
474	}
475	
476	void RdmaTransportManager::ResetOpenDeviceState(uint32_t phyId)
477	{
478	    std::lock_guard<std::mutex> lock(raMutex_);
479	    auto it = raInstances_.find(phyId);
480	    if (it != raInstances_.end() && it->second.refCount == 0) {
481	        raInstances_.erase(it);
482	    }
483	    if (raInstances_.empty()) {
484	        tsdOpened_ = false;
485	    }
486	}
487	
488	bool RdmaTransportManager::HandleRetiredDeviceIp(uint32_t phyId, net_addr_t& deviceIp)
489	{
490	    std::lock_guard<std::mutex> lock(raMutex_);
491	    auto it = raInstances_.find(phyId);
492	    if (it == raInstances_.end() || !it->second.deviceIpRetired || it->second.retiredIp.type != deviceIp.type) {
493	        return false;
494	    }
495	
496	    deviceIp = it->second.retiredIp;
497	    if (deviceIp.type == IpV4) {
498	        SHM_LOG_INFO("phyId=" << phyId << " device ip already retired : " << inet_ntoa(deviceIp.ip.ipv4));
499	        return true;
500	    } else if (deviceIp.type == IpV6) {
501	        char ipv6Str[INET6_ADDRSTRLEN];
502	        inet_ntop(AF_INET6, &deviceIp.ip.ipv6, ipv6Str, INET6_ADDRSTRLEN);
503	        SHM_LOG_INFO("phyId=" << phyId << " device ip already retired : " << ipv6Str);
504	        return true;
505	    }
506	    return false;
507	}
508	
509	bool RdmaTransportManager::RetireDeviceIp(uint32_t phyId, net_addr_t& deviceIp)
510	{
511	    auto isRetire = HandleRetiredDeviceIp(phyId, deviceIp);
512	    if (isRetire) {
513	        return true;
514	    }
515	
516	    uint32_t count = 0;
517	    std::vector<HccpInterfaceInfo> infos;
518	
519	    HccpRaGetIfAttr config;
520	    config.phyId = phyId;
521	    config.nicPosition = NETWORK_OFFLINE;
522	    config.isAll = false;
523	
524	    auto ret = DlHccpApi::RaGetIfNum(config, count);
525	    if (ret != 0 || count == 0) {
526	        SHM_LOG_ERROR("phyId=" << phyId << " get interface count failed: " << ret << ", count: " << count);
527	        return false;
528	    }
529	
530	    infos.resize(count);
531	    ret = DlHccpApi::RaGetIfAddrs(config, infos.data(), count);
532	    if (ret != 0) {
533	        SHM_LOG_ERROR("phyId=" << phyId << " get interface information failed: " << ret);
534	        return false;
535	    }
536	
537	    for (auto& info : infos) {
538	        SHM_LOG_DEBUG(
539	            "phyId=" << phyId << " found interface: ifname=" << info.ifname << ", scopeId=" << info.scopeId
540	                     << ", family=" << info.family);
541	        if (info.family == AF_INET && deviceIp.type == IpV4) {
542	            deviceIp.ip.ipv4 = info.ifaddr.ip.addr;
543	            deviceIp.type = IpV4;
544	            {
545	                std::lock_guard<std::mutex> lock(raMutex_);
546	                auto& state = raInstances_[phyId];
547	                state.retiredIp = deviceIp;
548	                state.deviceIpRetired = true;
549	            }
550	            SHM_LOG_DEBUG("phyId=" << phyId << " retire device ip success : " << inet_ntoa(deviceIp.ip.ipv4));
551	            return true;
552	        }
553	        if (info.family == AF_INET6 && deviceIp.type == IpV6) {
554	            deviceIp.ip.ipv6 = info.ifaddr.ip.addr6;
555	            deviceIp.type = IpV6;
556	            {
557	                std::lock_guard<std::mutex> lock(raMutex_);
558	                auto& state = raInstances_[phyId];
559	                state.retiredIp = deviceIp;
560	                state.deviceIpRetired = true;
561	            }
562	            char ipv6Str[INET6_ADDRSTRLEN];
563	            inet_ntop(AF_INET6, &deviceIp.ip.ipv6, ipv6Str, INET6_ADDRSTRLEN);
564	            SHM_LOG_DEBUG("phyId=" << phyId << " retire device ip success : " << ipv6Str);
565	            return true;
566	        }
567	    }
568	
569	    SHM_LOG_ERROR("phyId=" << phyId << " not found requested network device type " << deviceIp.type << " on NPU.");
570	    return false;
571	}
572	
573	bool RdmaTransportManager::RaRdevInit(uint32_t phyId, net_addr_t deviceIp, void*& rdmaHandle)
574	{
575	    std::lock_guard<std::mutex> lock(raMutex_);
576	    auto& state = raInstances_[phyId];
577	    if (state.rdmaHandle != nullptr) {
578	        SHM_LOG_INFO("phyId=" << phyId << " ra rdev already initialized.");
579	        rdmaHandle = state.rdmaHandle;
580	        return true;
581	    }
582	
583	    HccpRdevInitInfo info{};
584	    HccpRdev rdev{};
585	
586	    info.mode = NETWORK_OFFLINE;
587	    info.notifyType = NOTIFY;
588	    info.enabled2mbLite = true;
589	    rdev.phyId = phyId;
590	    rdev.family = (deviceIp.type == IpV4) ? AF_INET : AF_INET6;
591	    if (deviceIp.type == IpV4) {
592	        rdev.localIp.addr = deviceIp.ip.ipv4;
593	    } else if (deviceIp.type == IpV6) {
594	        rdev.localIp.addr6 = deviceIp.ip.ipv6;
595	    }
596	    SHM_LOG_DEBUG("phyId=" << phyId << " RaRdevInitV2, info=" << info << "rdev=" << rdev);
597	    auto ret = DlHccpApi::RaRdevInitV2(info, rdev, rdmaHandle);
598	    if (ret != 0) {
599	        SHM_LOG_ERROR("phyId=" << phyId << " Hccp Init RDev failed: " << ret);
600	        return false;
601	    }
602	
603	    state.rdmaHandle = rdmaHandle;
604	    SHM_LOG_INFO("phyId=" << phyId << " initialize RDev success.");
605	    return true;
606	}
607	
608	void RdmaTransportManager::ClearAllRegisterMRs()
609	{
610	    for (auto it = registerMRS_.begin(); it != registerMRS_.end(); ++it) {
611	        auto ret = DlHccpApi::RaDeregisterMR(rdmaHandle_, it->second.mrHandle);
612	        if (ret != 0) {
613	            SHM_LOG_WARN(
614	                rankId_ << " Unregister:" << (void*)(ptrdiff_t)it->first << " : " << it->second << " failed: " << ret);
615	        }
616	    }
617	    registerMRS_.clear();
618	}
619	
620	int RdmaTransportManager::CheckPrepareOptions(const shm::transport::HybmTransPrepareOptions& options)
621	{
622	    if (role_ != hybm_role_type::HYBM_ROLE_PEER) {
623	        SHM_LOG_INFO(rankId_ << " transport role: " << static_cast<uint32_t>(role_) << " check options passed.");
624	        return ACLSHMEM_SUCCESS;
625	    }
626	
627	    if (options.options.size() > rankCount_) {
628	        SHM_LOG_ERROR(
629	            rankId_ << " options size():" << options.options.size() << " larger than rank count: " << rankCount_);
630	        return ACLSHMEM_INVALID_PARAM;
631	    }
632	
633	    if (options.options.find(rankId_) == options.options.end()) {
634	        SHM_LOG_ERROR(rankId_ << " options not contains self rankId: " << rankId_);
635	        return ACLSHMEM_INVALID_PARAM;
636	    }
637	
638	    for (auto it = options.options.begin(); it != options.options.end(); ++it) {
639	        if (it->first >= rankCount_) {
640	            SHM_LOG_ERROR(
641	                rankId_ << " input options of nics contains rankId:" << it->first << ", rank count: " << rankCount_);
642	            return ACLSHMEM_INVALID_PARAM;
643	        }
644	    }
645	
646	    return ACLSHMEM_SUCCESS;
647	}
648	} // namespace device
649	} // namespace transport
650	} // namespace shm
