177	int FixedRanksQpManager::StartServerSide() noexcept
178	{
179	    if (rankId_ + 1U == rankCount_) {
180	        serverConnectResult = 0;
181	        return ACLSHMEM_SUCCESS;
182	    }
183	
184	    auto ret = CreateServerSocket();
185	    if (ret != ACLSHMEM_SUCCESS) {
186	        SHM_LOG_ERROR(rankId_ << " create server socket failed: " << ret);
187	        return ret;
188	    }
189	
190	    ret = GenerateWhiteList();
191	    if (ret != 0) {
192	        SHM_LOG_ERROR(rankId_ << " generate white list failed: " << ret);
193	        return ACLSHMEM_DL_FUNC_FAILED;
194	    }
195	
196	    serverConnectThread_ = std::make_shared<std::thread>([this]() {
197	        DlAclApi::AclrtSetDevice(userDeviceId_);
198	        auto ret = WaitConnectionsReady(serverConnections_);
199	        if (ret != ACLSHMEM_SUCCESS) {
200	            SHM_LOG_ERROR(rankId_ << " wait connection ready failed: " << ret);
201	            serverConnectResult = ret;
202	            return;
203	        }
204	        ret = CreateQpWaitingReady(serverConnections_, CONN_QP_AI_CORE, CONN_SERVER_SIDE);
205	        if (ret != ACLSHMEM_SUCCESS) {
206	            SHM_LOG_ERROR(rankId_ << " wait connection AI qp ready failed: " << ret);
207	            serverConnectResult = ret;
208	            return;
209	        }
210	
211	        serverConnectResult = ACLSHMEM_SUCCESS;
212	    });
213	
214	    return ACLSHMEM_SUCCESS;
215	}
