241	int FixedRanksQpManager::StartClientSide() noexcept
242	{
243	    if (rankId_ == 0U) {
244	        SHM_LOG_INFO(rankId_ << " need not connect to others.");
245	        clientConnectResult = ACLSHMEM_SUCCESS;
246	        return ACLSHMEM_SUCCESS;
247	    }
248	
249	    std::vector<HccpSocketConnectInfo> connectInfos;
250	    for (auto it = currentRanksInfo_.begin(); it != currentRanksInfo_.end(); ++it) {
251	        if (it->first >= rankId_) {
252	            continue; // client connect to small ranks.
253	        }
254	
255	        auto socketHandle = CreateLocalSocket();
256	        if (socketHandle == nullptr) {
257	            SHM_LOG_ERROR(rankId_ << " create local socket handle failed");
258	            CloseClientConnections();
259	            return ACLSHMEM_DL_FUNC_FAILED;
260	        }
261	
262	        net_addr_t addr;
263	        if (it->second.network.type == IpV4) {
264	            addr.type = IpV4;
265	            addr.ip.ipv4 = it->second.network.ip.ipv4.sin_addr;
266	        } else if (it->second.network.type == IpV6) {
267	            addr.type = IpV6;
268	            addr.ip.ipv6 = it->second.network.ip.ipv6.sin6_addr;
269	        }
270	
271	        clientConnections_.emplace(it->first, ConnectionChannel{addr, socketHandle});
272	        HccpSocketConnectInfo connectInfo;
273	        connectInfo.handle = socketHandle;
274	        if (it->second.network.type == IpV4) {
275	            connectInfo.remoteIp.addr = it->second.network.ip.ipv4.sin_addr;
276	        } else if (it->second.network.type == IpV6) {
277	            connectInfo.remoteIp.addr6 = it->second.network.ip.ipv6.sin6_addr;
278	        }
279	        connectInfo.port = (it->second.network.type == IpV4) ? it->second.network.ip.ipv4.sin_port :
280	                                                               it->second.network.ip.ipv6.sin6_port;
281	        bzero(connectInfo.tag, sizeof(connectInfo.tag));
282	        SHM_LOG_DEBUG(rankId_ << " add connecting server " << connectInfo);
283	        connectInfos.emplace_back(connectInfo);
284	    }
285	
286	    for (size_t i = 0; i < connectInfos.size(); i += RA_MAX_BATCH_NUM) {
287	        size_t currentBatchSize =
288	            (connectInfos.size() - i) >= RA_MAX_BATCH_NUM ? RA_MAX_BATCH_NUM : (connectInfos.size() - i);
289	        auto batchStart = connectInfos.begin() + i;
290	        auto batchEnd = batchStart + currentBatchSize;
291	        std::vector<HccpSocketConnectInfo> currentBatch(batchStart, batchEnd);
292	
293	        auto ret = DlHccpApi::RaSocketBatchConnect(currentBatch.data(), currentBatch.size());
294	        if (ret != 0) {
295	            SHM_LOG_ERROR(
296	                rankId_ << " connect to all servers failed: " << ret << ", servers count = " << connectInfos.size());
297	            CloseClientConnections();
298	            return ACLSHMEM_DL_FUNC_FAILED;
299	        }
300	    }
301	
302	    InitClientConnectThread();
303	    return ACLSHMEM_SUCCESS;
304	}
