306	int FixedRanksQpManager::GenerateWhiteList() noexcept
307	{
308	    std::vector<HccpSocketWhiteListInfo> whitelist;
309	    for (auto it = currentRanksInfo_.begin(); it != currentRanksInfo_.end(); ++it) {
310	        if (it->first <= rankId_) {
311	            continue; // small id as server, large id as client
312	        }
313	        HccpSocketWhiteListInfo info{};
314	        net_addr_t addr;
315	        if (it->second.network.type == IpV4) {
316	            addr.type = IpV4;
317	            addr.ip.ipv4 = it->second.network.ip.ipv4.sin_addr;
318	            info.remoteIp.addr = it->second.network.ip.ipv4.sin_addr;
319	        } else if (it->second.network.type == IpV6) {
320	            addr.type = IpV6;
321	            addr.ip.ipv6 = it->second.network.ip.ipv6.sin6_addr;
322	            info.remoteIp.addr6 = it->second.network.ip.ipv6.sin6_addr;
323	        }
324	        info.connLimit = rankCount_;
325	        bzero(info.tag, sizeof(info.tag));
326	        whitelist.emplace_back(info);
327	        serverConnections_.emplace(it->first, ConnectionChannel{addr, serverSocketHandle_});
328	    }
329	
330	    if (whitelist.empty()) {
331	        return ACLSHMEM_SUCCESS;
332	    }
333	
334	    for (size_t i = 0; i < whitelist.size(); i += RA_MAX_BATCH_NUM) {
335	        size_t currentBatchSize =
336	            (whitelist.size() - i) >= RA_MAX_BATCH_NUM ? RA_MAX_BATCH_NUM : (whitelist.size() - i);
337	        auto batchStart = whitelist.begin() + i;
338	        auto batchEnd = batchStart + currentBatchSize;
339	        std::vector<HccpSocketWhiteListInfo> currentBatch(batchStart, batchEnd);
340	        auto ret = DlHccpApi::RaSocketWhiteListAdd(serverSocketHandle_, currentBatch.data(), currentBatch.size());
341	        if (ret != 0) {
342	            SHM_LOG_ERROR(rankId_ << " socket handle add white list failed: " << ret);
343	            return ACLSHMEM_INNER_ERROR;
344	        }
345	    }
346	
347	    return ACLSHMEM_SUCCESS;
348	}
