350	int FixedRanksQpManager::WaitConnectionsReady(std::unordered_map<uint32_t, ConnectionChannel>& connections) noexcept
351	{
352	    IpType type{};
353	    uint32_t cnt = 0;
354	    auto start = std::chrono::steady_clock::now();
355	    constexpr auto TIMEOUT_MINUTES = 2;
356	    auto timeout = start + std::chrono::minutes(TIMEOUT_MINUTES);
357	    SHM_LOG_DEBUG(rankId_ << " begin wait connections, size=" << connections.size());
358	
