500	        SHM_LOG_DEBUG(rankId_ << ":" << sideName << " create qp success, qptype=" << qpType);
501	
502	        for (auto pos = currentLocalMrs_.begin(); pos != currentLocalMrs_.end(); ++pos) {
503	            HccpMrInfo info{};
504	            info.addr = (void*)(ptrdiff_t)pos->second.address;
505	            info.size = pos->second.size;
506	            info.access = accessLevel;
507	            ret = DlHccpApi::RaMrReg(it->second.qpHandles[qpType], info);
508	            if (ret != 0) {
509	                SHM_LOG_ERROR(rankId_ << ":" << sideName << " register MR failed: " << ret);
510	                if (it->second.qpHandles[qpType] != nullptr) {
