519	
520	        ret = DlHccpApi::RaQpConnectAsync(it->second.qpHandles[qpType], it->second.socketFd);
521	        if (ret != 0) {
522	            SHM_LOG_ERROR(rankId_ << ":" << sideName << " connect AI QP to " << it->first << " failed: " << ret);
523	            if (it->second.qpHandles[qpType] != nullptr) {
