525	                it->second.qpHandles[qpType] = nullptr;
526	            }
527	            cleanupQps(it);
528	            return ACLSHMEM_DL_FUNC_FAILED;
529	        }
530	    }
531	
532	    SHM_LOG_DEBUG(rankId_ << ":" << sideName << " begin wait create qp ready.");
533	    auto start = std::chrono::steady_clock::now();
534	    auto timeout = start + std::chrono::minutes(1);
535	    while (std::chrono::steady_clock::now() < timeout) {
536	        int connectingCount = 0;
537	        for (auto it = connections.begin(); it != connections.end(); ++it) {
538	            int status = 0;
