540	            if (ret != 0) {
541	                SHM_LOG_ERROR(rankId_ << ":" << sideName << " get AI QP status to " << it->first << " failed: " << ret);
542	                cleanupQps(connections.end());
543	                return ACLSHMEM_DL_FUNC_FAILED;
