545	
546	            // rs_qp_status: 0-disconnect, 1-connected, 2-timeout, 3-connecting, 4-fd_close, 5-pause
547	            SHM_LOG_DEBUG(rankId_ << ":" << sideName << " get create qp status to " << it->first << "=" << status);
548	            if (status != 1) {
549	                connectingCount++;
550	            }
551	        }
552	        if (connectingCount == 0) {
553	            return FillQpInfo(qpType);
554	        }
555	        std::this_thread::sleep_for(std::chrono::milliseconds(10));
556	    }
557	    SHM_LOG_ERROR(rankId_ << ":" << sideName << " wait create qp ready timeout");
558	    cleanupQps(connections.end());
